  const cols=[58,140,650,800,1120];ctx.fillStyle='#103d83';ctx.fillRect(58,365,1384,52);ctx.fillStyle='#fff';ctx.font='bold 20px Arial';['STT','HỌ VÀ TÊN / MÃ VÕ SINH','NĂM SINH','LỚP','TRẠNG THÁI'].forEach((s,i)=>ctx.fillText(s,cols[i]+12,398));
