function Stat({label,value,detail,icon:Icon,color,onClick}:any){return <button type="button" disabled={!onClick} onClick={onClick} className="stat-card stat-shortcut" aria-label={onClick?label+' · Mở tab tương ứng':label}><div className="stat-top"><span>{label}</span><div className={'stat-icon '+color}><Icon size={20}/></div></div><strong className="stat-value">{value}</strong><p>{detail}</p></button>}
function Filters({query,onQuery,classId,onClass,classes,placeholder}:any){return <div className="filters"><div className="search-field"><Search size={18}/><input value={query} onChange={e=>onQuery(e.target.value)} placeholder={placeholder}/>{query&&<button className="icon-btn" aria-label="Xóa tìm kiếm" onClick={()=>onQuery('')}><X size={15}/></button>}</div><select aria-label="Lọc theo lớp" value={classId} onChange={e=>onClass(e.target.value)}><option value="">Tất cả các lớp được cấp</option>{classes.map((c:any)=><option value={c.id} key={c.id}>{c.data.name}</option>)}</select></div>}
